/// One golden baseline: a name, what to render, and what a human should see.
///
/// The `expectation` string is the part that matters most. A golden that fails
/// with only a filename tells the next person nothing about whether the new
/// picture is right; a golden that says "the card below the dismissed one has
/// not moved" tells them exactly what to look for in the triptych.
#[derive(Debug, Clone)]
pub struct GoldenCase {
    /// Baseline file name, without extension.
    pub name: String,
    /// What to render.
    pub spec: RenderSpec,
    /// What the picture is supposed to show, in prose.
    pub expectation: String,
}

