/// The complete golden corpus.
///
/// Every scenario at every key instant, plus a reduce-motion variant of each
/// animated scenario and a light-theme variant of the resting ones. This is the
/// same list the marketing assets come from — D25's point being that a corpus
/// maintained twice is a corpus that disagrees with itself.
#[must_use]
pub fn golden_plan() -> Vec<GoldenCase> {
    let mut cases = Vec::new();

    for &scenario in Scenario::all() {
        let fixture = scenario.fixture();
        for instant in fixture.key_instants {
            cases.push(GoldenCase {
                name: format!("{}--{}", scenario.slug(), instant.name),
                spec: RenderSpec::golden(scenario, instant.clock()),
                expectation: instant.expectation.to_owned(),
            });
        }

        // Reduce-motion (D13): the very first frame must already be the settled
        // frame. Rendering it at t=0 is what proves motion is never the only
        // carrier of meaning — if this picture is missing information the
        // animated one has, the design is wrong, not the test.
        if fixture.gesture != Gesture::None {
            cases.push(GoldenCase {
                name: format!("{}--reduce-motion", scenario.slug()),
                spec: RenderSpec::golden(scenario, VirtualClock::ZERO).with_reduce_motion(true),
                expectation: format!(
                    "reduce-motion: identical to the settled frame of {} at t=0, \
                     with no intermediate position visible",
                    scenario.slug()
                ),
            });
        }
    }

    // Light theme on the resting states. Every scenario in both themes would
    // double the corpus for very little extra coverage; the resting states are
    // where contrast and elevation actually get decided.
    for scenario in [
        Scenario::StackFull,
        Scenario::DockCollapsed,
        Scenario::EditorAnnotating,
        Scenario::EditorColorPopover,
        Scenario::EditorArrowStyles,
        Scenario::RecordingSettings,
        Scenario::VideoEditing,
        Scenario::VideoEditingNarrow,
        Scenario::SettingsAfterCapture,
        Scenario::EditorCrop,
        Scenario::EditorRedact,
        Scenario::SmartFrameUntouched,
        Scenario::SmartFrameOneClick,
        Scenario::SmartFrameExpanded,
        Scenario::RecordingCamera,
        Scenario::RecordingPresenter,
        Scenario::CameraSettings,
        Scenario::SensitiveReview,
    ] {
        cases.push(GoldenCase {
            name: format!("{}--light", scenario.slug()),
            spec: RenderSpec::golden(scenario, VirtualClock::ZERO).with_theme(egui::Theme::Light),
            expectation: format!(
                "{} in the light theme: text contrast and card elevation must \
                 both survive the inversion",
                scenario.slug()
            ),
        });
    }

    cases.push(GoldenCase {
        name: "video-editing--reduce-motion".to_owned(),
        spec: RenderSpec::golden(Scenario::VideoEditing, VirtualClock::ZERO)
            .with_reduce_motion(true),
        expectation:
            "the complete editor remains usable with all movement disabled and no control hidden"
                .to_owned(),
    });

    // A 1x render, because grayscale text AA (D22 cost 4) is at its worst at 1x
    // and that is precisely where a font or gamma regression will first show.
    cases.push(GoldenCase {
        name: "stack-full--1x".to_owned(),
        spec: RenderSpec::golden(Scenario::StackFull, VirtualClock::ZERO).with_scale(1.0),
        expectation: "the stack at 1x: grayscale text anti-aliasing, where \
                      subpixel positioning and gamma problems are visible"
            .to_owned(),
    });

    cases.push(GoldenCase {
        name: "settings-after-capture--compact".to_owned(),
        spec: RenderSpec::golden(Scenario::SettingsAfterCapture, VirtualClock::ZERO)
            .with_size_pt((620.0, 1_250.0)),
        expectation: "After Capture at the minimum window width: every action reflows into a \
                      two-column card without horizontal scrolling, clipped labels, or an inert \
                      unavailable checkbox"
            .to_owned(),
    });

    for scenario in [
        Scenario::SmartFrameUntouched,
        Scenario::SmartFrameOneClick,
        Scenario::SmartFrameExpanded,
    ] {
        cases.push(GoldenCase {
            name: format!("{}--compact", scenario.slug()),
            spec: RenderSpec::golden(scenario, VirtualClock::ZERO).with_size_pt((760.0, 560.0)),
            expectation: format!(
                "{} in a compact editor: primary actions and labels remain visible without a dense default panel",
                scenario.slug()
            ),
        });
    }

    cases
}

/// One store asset to produce.
#[derive(Debug, Clone)]
pub struct StoreCase {
    /// Output path, relative to the output directory.
    pub relative_path: PathBuf,
    /// What to render.
    pub spec: RenderSpec,
    /// The target it was built for.
    pub target_id: String,
}

/// The store assets for a manifest.
///
/// Every required target, every locale, every marketing scenario — derived, so
/// adding a store is a line of TOML and adding a locale is a word.
///
/// # Errors
///
/// Returns an error if a target's dimensions are not a whole number of points.
pub fn store_plan(
    manifest: &StoreManifest,
    only_target: Option<&str>,
    required_only: bool,
) -> Result<Vec<StoreCase>> {
    // The marketing sequence: what Scrozz is, then what makes it different.
    // Ordered, because store listings show them in order and the first one is
    // the only one most people see.
    const SHOWCASE: [(Scenario, u64); 4] = [
        (Scenario::StackFull, 0),
        (Scenario::StackEntering, 180),
        (Scenario::EditorAnnotating, 0),
        (Scenario::DockCollapsed, 0),
    ];

    let mut out = Vec::new();
    for target in &manifest.targets {
        if let Some(id) = only_target {
            if target.id != id {
                continue;
            }
        } else if required_only && !target.required {
            continue;
        }
        for locale in &target.locales {
            for (i, (scenario, at_ms)) in SHOWCASE.iter().enumerate() {
                let spec =
                    RenderSpec::store(*scenario, VirtualClock::from_millis(*at_ms), target, locale);
                // Fail here rather than at upload time if the target's pixel
                // size is not a whole number of points.
                spec.resolved_size_px()?;
                out.push(StoreCase {
                    relative_path: Path::new(&target.id).join(locale).join(format!(
                        "{:02}-{}.png",
                        i + 1,
                        scenario.slug()
                    )),
                    spec,
                    target_id: target.id.clone(),
                });
            }
        }
    }
    Ok(out)
}

/// One documentation still.
#[derive(Debug, Clone)]
pub struct DocsCase {
    /// Output path, relative to the output directory.
    pub relative_path: PathBuf,
    /// What to render.
    pub spec: RenderSpec,
    /// A frame run to emit instead of a single still, when animated.
    pub sequence: Option<SequenceSpec>,
    /// Alt text. Written here so it is version-controlled next to the image
    /// rather than retyped into Markdown and then quietly forgotten.
    pub alt: String,
}

/// The README and documentation assets.
#[must_use]
pub fn docs_plan() -> Vec<DocsCase> {
    let mut out = Vec::new();
    for &scenario in Scenario::all() {
        let fixture = scenario.fixture();
        out.push(DocsCase {
            relative_path: PathBuf::from(format!("{}.png", scenario.slug())),
            spec: RenderSpec::docs(scenario, VirtualClock::ZERO),
            sequence: None,
            alt: fixture.intent.to_owned(),
        });
        if let Some(seq) = fixture.sequence {
            out.push(DocsCase {
                relative_path: PathBuf::from(format!("{}-frames", scenario.slug())),
                spec: RenderSpec::docs(scenario, VirtualClock::ZERO),
                sequence: Some(seq),
                alt: format!("{} (animated)", fixture.intent),
            });
        }
    }
    out
}

