/// One file the generator wrote.
#[derive(Debug, Clone)]
pub struct GeneratedAsset {
    /// Where it was written.
    pub path: PathBuf,
    /// Pixel dimensions.
    pub size: (u32, u32),
    /// The content fingerprint, for the index.
    pub fingerprint: String,
    /// Alt text or expectation, if there is one.
    pub description: String,
}

/// The result of generating a batch.
#[derive(Debug, Clone, Default)]
pub struct GeneratedBatch {
    /// Everything written.
    pub assets: Vec<GeneratedAsset>,
    /// Frame directories that still need encoding, with the command to do it.
    pub encode_commands: Vec<String>,
}

impl GeneratedBatch {
    /// A human-readable index, written alongside the assets.
    ///
    /// It carries fingerprints, so `git diff` on the index alone says which
    /// pictures changed without opening any of them.
    #[must_use]
    pub fn index(&self) -> String {
        use fmt::Write as _;
        let mut s = String::from(
            "# Generated by the Scrozz screenshot harness (D25).\n\
             # Do not edit, and do not add a hand-taken screenshot to this directory.\n\n",
        );
        for a in &self.assets {
            let _ = writeln!(
                s,
                "{}\t{}x{}\t{}\t{}",
                a.path.display(),
                a.size.0,
                a.size.1,
                a.fingerprint,
                a.description
            );
        }
        s
    }
}

impl SoftwareRenderer {
    /// Renders one golden case.
    ///
    /// # Errors
    ///
    /// Propagates render errors.
    pub fn render_case(&self, case: &GoldenCase) -> Result<Image> {
        self.render(&case.spec)
    }

    /// Renders and compares the whole golden corpus.
    ///
    /// Returns every failure rather than stopping at the first: one theme change
    /// breaks forty baselines, and being told about them one CI run at a time is
    /// how people come to hate golden tests.
    ///
    /// # Errors
    ///
    /// Propagates render and I/O errors, including a missing committed baseline.
    /// A pixel mismatch is returned in the `Vec`, not as an error.
    pub fn check_goldens(&self, store: &GoldenStore) -> Result<Vec<GoldenFailure>> {
        let mut failures = Vec::new();
        for case in golden_plan() {
            let image = self.render_case(&case)?;
            if let GoldenOutcome::Mismatched(f) = store.compare(&case.name, &image)? {
                failures.push(*f);
            }
        }
        Ok(failures)
    }

    /// Writes the store assets under `out_dir`.
    ///
    /// # Errors
    ///
    /// Propagates render and I/O errors, including the refusal to render a
    /// placeholder into a store asset.
    pub fn generate_store(
        &self,
        manifest: &StoreManifest,
        out_dir: &Path,
        only_target: Option<&str>,
        required_only: bool,
    ) -> Result<GeneratedBatch> {
        let mut batch = GeneratedBatch::default();
        for case in store_plan(manifest, only_target, required_only)? {
            let image = self.render(&case.spec)?;
            let path = out_dir.join(&case.relative_path);
            if let Some(parent) = path.parent() {
                std::fs::create_dir_all(parent)?;
            }
            image.write_png(&path)?;
            batch.assets.push(GeneratedAsset {
                size: (image.width(), image.height()),
                fingerprint: image.fingerprint(),
                description: format!(
                    "{} for {}",
                    case.spec.scenario.fixture().intent,
                    case.target_id
                ),
                path,
            });
        }
        Ok(batch)
    }

    /// Writes the documentation assets under `out_dir`.
    ///
    /// Animated cases become a numbered directory of frames plus the exact
    /// `ffmpeg` command to encode them. The harness deliberately does not shell
    /// out: encoding is not its job, `image` cannot write APNG or WebM, and
    /// adding a video encoder as a dependency to produce a README GIF would be a
    /// poor trade.
    ///
    /// # Errors
    ///
    /// Propagates render and I/O errors.
    pub fn generate_docs(&self, out_dir: &Path) -> Result<GeneratedBatch> {
        let mut batch = GeneratedBatch::default();
        for case in docs_plan() {
            match case.sequence {
                None => {
                    let image = self.render(&case.spec)?;
                    let path = out_dir.join(&case.relative_path);
                    if let Some(parent) = path.parent() {
                        std::fs::create_dir_all(parent)?;
                    }
                    image.write_png(&path)?;
                    batch.assets.push(GeneratedAsset {
                        size: (image.width(), image.height()),
                        fingerprint: image.fingerprint(),
                        description: case.alt.clone(),
                        path,
                    });
                }
                Some(seq) => {
                    let dir = out_dir.join(&case.relative_path);
                    std::fs::create_dir_all(&dir)?;
                    let frames = self.render_sequence(&case.spec, seq)?;
                    for (i, (clock, image)) in frames.iter().enumerate() {
                        let path = dir.join(format!("frame-{i:04}.png"));
                        image.write_png(&path)?;
                        batch.assets.push(GeneratedAsset {
                            size: (image.width(), image.height()),
                            fingerprint: image.fingerprint(),
                            description: format!("{} @ {}", case.alt, clock),
                            path,
                        });
                    }
                    batch.encode_commands.push(seq.ffmpeg_command(&dir));
                }
            }
        }
        Ok(batch)
    }

    /// Regenerates the committed golden baselines.
    ///
    /// # Errors
    ///
    /// Propagates render and I/O errors.
    pub fn generate_goldens(&self, store: &GoldenStore) -> Result<GeneratedBatch> {
        let updating = store.clone().with_update(true);
        let mut batch = GeneratedBatch::default();
        for case in golden_plan() {
            let image = self.render_case(&case)?;
            updating.compare(&case.name, &image)?;
            batch.assets.push(GeneratedAsset {
                path: updating.path_for(&case.name),
                size: (image.width(), image.height()),
                fingerprint: image.fingerprint(),
                description: case.expectation,
            });
        }
        Ok(batch)
    }
}

impl SequenceSpec {
    /// The `ffmpeg` invocation that turns this run of frames into a loop.
    ///
    /// Printed rather than executed, so the person running it can see exactly
    /// what would happen and change it.
    #[must_use]
    pub fn ffmpeg_command(&self, dir: &Path) -> String {
        let fps = 1000_u64.checked_div(self.step_ms).map_or(60, |f| f.max(1));
        format!(
            "ffmpeg -y -framerate {fps} -i {}/frame-%04d.png \
             -vf 'split[a][b];[a]palettegen=stats_mode=diff[p];[b][p]paletteuse' \
             {}.gif",
            dir.display(),
            dir.display()
        )
    }
}

// ===========================================================================
// The entry point `lib.rs` re-exports
// ===========================================================================

/// Renders one scenario for one profile, as PNG bytes.
///
/// The narrow, stable entry point: everything else in this module is machinery
/// behind it. `seed` overrides the fixture's own seed, which is only ever useful
/// for proving that a seed change actually changes the picture.
///
/// # Errors
///
/// Returns an error when the scenario has no registered scene, when a store
/// render would contain a placeholder, or when encoding fails.
pub fn render(scenario: &Scenario, profile: &Profile, seed: u64) -> Result<Vec<u8>> {
    let spec = RenderSpec::for_profile(*scenario, profile.clone()).with_seed(seed);
    SoftwareRenderer::production().render(&spec)?.to_png()
}
